"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

interface RoomType {
  id: number;
  name: string;
}

interface Room {
  id: number;
  room_number: string;
  building: string;
  capacity: number;
  type_id: number;
  is_available: boolean;
  type?: RoomType | null;
}

interface RoomResponse {
  success: boolean;
  message: string;
  data: Room;
}

interface RoomTypesResponse {
  success: boolean;
  message: string;
  data: RoomType[];
}

export default function AdminRoomDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const [room, setRoom] = useState<Room | null>(null);
  const [types, setTypes] = useState<RoomType[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [form, setForm] = useState({
    room_number: "",
    building: "",
    capacity: "",
    type_id: "",
    is_available: true,
  });

  async function load() {
    try {
      setLoading(true);
      setError(null);
      const [roomRes, typeRes] = await Promise.all([
        api.get<RoomResponse>(`/admin/rooms/${id}`),
        api.get<RoomTypesResponse>("/admin/room-types"),
      ]);
      setRoom(roomRes.data);
      setTypes(typeRes.data ?? []);
      setForm({
        room_number: roomRes.data.room_number ?? "",
        building: roomRes.data.building ?? "",
        capacity: String(roomRes.data.capacity ?? ""),
        type_id: String(roomRes.data.type_id ?? ""),
        is_available: Boolean(roomRes.data.is_available),
      });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load room.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, [id]);

  async function onSave() {
    try {
      setSaving(true);
      setError(null);
      setSuccess(null);
      await api.patch(`/admin/rooms/${id}`, {
        room_number: form.room_number.trim().toUpperCase(),
        building: form.building.trim(),
        capacity: Number(form.capacity),
        type_id: Number(form.type_id),
        is_available: form.is_available,
      });
      setSuccess("Room updated successfully.");
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to save room.");
    } finally {
      setSaving(false);
    }
  }

  async function onToggle() {
    try {
      setSaving(true);
      setError(null);
      setSuccess(null);
      await api.patch(`/admin/rooms/${id}/toggle`, {});
      setSuccess("Room availability updated.");
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to toggle room.");
    } finally {
      setSaving(false);
    }
  }

  async function onDelete() {
    try {
      setSaving(true);
      setError(null);
      await api.delete(`/admin/rooms/${id}`);
      router.push("/admin/rooms");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to delete room.");
      setSaving(false);
    }
  }

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Room Details">
      <div style={{ maxWidth: 860, margin: "0 auto" }} className="space-y-4">
        <button className="btn btn-ghost btn-sm" onClick={() => router.push("/admin/rooms")}>Back to Rooms</button>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}
        {success && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#bbf7d0", background: "#f0fdf4", color: "#166534" }}>{success}</div>}

        {loading || !room ? (
          <div className="card card-body">Loading...</div>
        ) : (
          <div className="card card-body space-y-4">
            <div className="flex items-center justify-between">
              <h1 className="text-lg font-semibold">{room.room_number}</h1>
              <span className={`badge ${room.is_available ? "badge-green" : "badge-red"}`}>{room.is_available ? "Available" : "Unavailable"}</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="form-group">
                <label className="form-label">Room Number</label>
                <input value={form.room_number} onChange={(e) => setForm((p) => ({ ...p, room_number: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">Building</label>
                <input value={form.building} onChange={(e) => setForm((p) => ({ ...p, building: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">Capacity</label>
                <input type="number" min={1} value={form.capacity} onChange={(e) => setForm((p) => ({ ...p, capacity: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">Type</label>
                <select value={form.type_id} onChange={(e) => setForm((p) => ({ ...p, type_id: e.target.value }))}>
                  <option value="">Select type</option>
                  {types.map((t) => <option key={t.id} value={String(t.id)}>{t.name}</option>)}
                </select>
              </div>
            </div>

            <label className="flex items-center gap-2 text-sm">
              <input type="checkbox" checked={form.is_available} onChange={(e) => setForm((p) => ({ ...p, is_available: e.target.checked }))} />
              Available for booking
            </label>

            <div className="flex flex-wrap gap-2">
              <button className="btn btn-primary btn-sm" onClick={onSave} disabled={saving}>{saving ? "Saving..." : "Save Changes"}</button>
              <button className="btn btn-outline btn-sm" onClick={onToggle} disabled={saving}>
                {room.is_available ? "Disable Room" : "Enable Room"}
              </button>
              <button className="btn btn-sm" style={{ background: "var(--color-error-light)", color: "var(--color-error)" }} onClick={onDelete} disabled={saving}>
                Delete Room
              </button>
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}
